"""Keep revisions autogenerated on SQLite portable to PostgreSQL (GH #342).

Autogenerate against the default SQLite database emits things Postgres rejects
or never sees, and neither ``alembic check`` nor the boot check notices:

* Boolean ``server_default`` rendered as ``sa.text('0')`` — Postgres refuses an
  integer default on a boolean column. :func:`rewrite_boolean_defaults` and
  :func:`render_boolean_default` emit ``sa.false()`` / ``sa.true()`` instead.
* Expression indexes (``lower(email)``) are skipped on SQLite because it cannot
  reflect them. :func:`warn_unverifiable_expression_indexes` names the ones a
  revision may have missed.
* ``op.drop_table`` leaves ``CREATE TYPE`` behind on Postgres, so a downgrade
  followed by an upgrade fails with ``DuplicateObject``. Use
  :func:`drop_enums_if_postgres` in the revision's ``downgrade``.

``simple_module_db.migrations`` wires the first two into the hooks every
``env.py`` already passes to Alembic.
"""

from __future__ import annotations

import logging
from collections.abc import Iterator
from typing import Any

import sqlalchemy as sa
from alembic.operations.ops import AddColumnOp, AlterColumnOp, CreateTableOp
from simple_module_core.diagnostics._expression_index import (
    expression_index_advice,
    find_expression_indexes,
)
from sqlalchemy.dialects import postgresql
from sqlalchemy.schema import DefaultClause
from sqlalchemy.sql.elements import ColumnElement, False_, TextClause, True_

logger = logging.getLogger("alembic.env")

_FALSE_LITERALS = frozenset({"0", "false"})
_TRUE_LITERALS = frozenset({"1", "true"})


def boolean_default_for(default: Any) -> ColumnElement[bool] | None:
    """Map a Boolean ``server_default`` spelled as 0/1/true/false to ``sa.false()``/``sa.true()``.

    Accepts a ``DefaultClause``, ``text()``, bare string, or SQLAlchemy
    ``true()``/``false()``; returns ``None`` when it is none of those literals.
    """
    arg = default.arg if isinstance(default, DefaultClause) else default
    if isinstance(arg, False_):
        return sa.false()
    if isinstance(arg, True_):
        return sa.true()
    text = arg.text if isinstance(arg, TextClause) else arg
    if not isinstance(text, str):
        return None
    literal = text.strip().strip("()").strip("'\"").lower()
    if literal in _FALSE_LITERALS:
        return sa.false()
    if literal in _TRUE_LITERALS:
        return sa.true()
    return None


def render_boolean_default(obj: Any, autogen_context: Any) -> str | bool:
    """``render_item`` branch: render ``true()``/``false()`` defaults as such.

    SQLAlchemy compiles ``false()`` under SQLite to ``0``, which Alembic then
    renders as ``sa.text('0')``. Intercepting the ``server_default`` item keeps
    the portable expression the model declared.
    """
    arg = obj.arg if isinstance(obj, DefaultClause) else obj
    if not isinstance(arg, (True_, False_)):
        return False
    prefix = autogen_context.opts.get("sqlalchemy_module_prefix", "sa.")
    return f"{prefix}{'true' if isinstance(arg, True_) else 'false'}()"


def iter_ops_recursive(container: Any) -> Iterator[Any]:
    """Yield every op under ``container``, descending into nested op groups.

    Autogenerate does not emit a flat op list: index operations for a table are
    grouped inside a ``ModifyTableOps`` container alongside the top-level
    ``CreateTableOp``/``DropTableOp``. A dedup check that only looks at
    ``container.ops`` therefore sees no ``CreateIndexOp`` at all and re-injects
    an index the dialect already emitted — which is exactly how a dialect that
    *can* reflect expression-based indexes (PostgreSQL) ended up with a
    duplicate ``CREATE INDEX`` in its initial migration.
    """
    for op in container.ops:
        yield op
        if hasattr(op, "ops"):
            yield from iter_ops_recursive(op)


def rewrite_boolean_defaults(upgrade_ops: Any) -> None:
    """Rewrite integer-looking defaults on Boolean columns in a revision's op tree.

    Covers columns of ``create_table``, ``add_column`` and ``alter_column``
    (the latter via ``existing_type``).
    """
    for op in iter_ops_recursive(upgrade_ops):
        if isinstance(op, CreateTableOp):
            columns = [c for c in op.columns if isinstance(c, sa.Column)]
        elif isinstance(op, AddColumnOp):
            columns = [op.column]
        elif isinstance(op, AlterColumnOp):
            replacement = None
            if isinstance(op.existing_type or op.modify_type, sa.Boolean):
                replacement = boolean_default_for(op.modify_server_default)
            if replacement is not None:
                op.modify_server_default = replacement
            continue
        else:
            continue
        for column in columns:
            if not isinstance(column.type, sa.Boolean) or column.server_default is None:
                continue
            replacement = boolean_default_for(column.server_default)
            if replacement is not None:
                column.server_default = DefaultClause(replacement)


def warn_unverifiable_expression_indexes(
    dialect_name: str | None, metadata: sa.MetaData, upgrade_ops: Any = None
) -> list:
    """Warn when a revision autogenerated on SQLite may miss expression indexes.

    With ``upgrade_ops`` (what the revision hook passes, after re-emitting the
    indexes of new tables), only indexes on tables the revision touches and
    does not create are named: a fresh initial schema creates them, and a
    revision on another table cannot have dropped them (GH #917). Without it,
    every expression index in ``metadata`` is named.

    A warning rather than an error: SQLite can neither confirm nor refute the
    drift, and a PostgreSQL run is the real gate. Returns the
    ``(table, index)`` pairs it warned about.
    """
    if dialect_name != "sqlite":
        return []
    found = find_expression_indexes(metadata.tables.values())
    if upgrade_ops is not None:
        ops = list(iter_ops_recursive(upgrade_ops))
        touched = {getattr(op, "table_name", None) for op in ops}
        emitted = {getattr(op, "index_name", None) for op in ops}
        found = [(t, i) for t, i in found if t in touched and i not in emitted]
    if not found:
        return []
    listing = "\n".join(f"    - {index} on {table}" for table, index in found)
    logger.warning(
        "\n%s\n"
        "WARNING: autogenerating on SQLite. SQLite cannot reflect expression indexes,\n"
        "so this revision does NOT account for the following on the tables it\n"
        "changes, and `alembic check` will not notice drift:\n"
        "%s\n"
        "If the change affects them, add them to the revision by hand and\n"
        "%s.\n"
        "%s",
        "=" * 78,
        listing,
        expression_index_advice(),
        "=" * 78,
    )
    return found


def drop_enums_if_postgres(op: Any, *names: str) -> None:
    """Drop the named enum types on PostgreSQL; a no-op elsewhere.

    Call it at the end of ``downgrade()``, after the tables that use the types
    are dropped. ``op.drop_table`` leaves the ``CREATE TYPE`` behind, and
    autogenerate never emits the ``Enum.drop``, so without this a
    ``downgrade`` followed by an ``upgrade`` fails with ``DuplicateObject``.
    SQLite has no such object, which is why the round trip passes there.
    """
    bind = op.get_bind()
    if bind.dialect.name != "postgresql":
        return
    for name in names:
        postgresql.ENUM(name=name).drop(bind, checkfirst=True)
